package es.gestionpersonas.solicitud.modelo; 
import es.gestionpersonas.auditoria.EntidadAuditable;
import jakarta.persistence.*; import org.hibernate.annotations.JdbcTypeCode; import org.hibernate.type.SqlTypes; import java.time.LocalDateTime; import java.util.Map; @Entity @Table(name="accion_solicitud") public class AccionSolicitud extends EntidadAuditable { @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(name="solicitud_id",nullable=false) private Long requestId; @Column(name="entidad_actor_id") private Long actorEntityId; @Column(name="tipo_accion",nullable=false,length=60) private String actionType; @Column(name="fecha_creacion",nullable=false) private LocalDateTime createdAt; @JdbcTypeCode(SqlTypes.JSON) @Column(name="datos",columnDefinition="json") private Map<String,Object> data; protected AccionSolicitud(){} public AccionSolicitud(Long requestId,Long actor,String type,Map<String,Object> data){this.requestId=requestId;actorEntityId=actor;actionType=type;this.data=data;createdAt=LocalDateTime.now().withNano(0);} public Long getId(){return id;} public Long getRequestId(){return requestId;} public Long getActorEntityId(){return actorEntityId;} public String getActionType(){return actionType;} public LocalDateTime getCreatedAt(){return createdAt;} public Map<String,Object> getData(){return data;} }
